"""r4-fixes 1.1: which raw .sofar reads the PreToolUse rewrite caught and which it missed (round 4, sofar arm, Claude).
Read-only. Prints each raw read with REWRITTEN/MISSED and a reason class."""
import json, re, sys
from collections import Counter
import claude_sessions as cs

def main():
    rnd = 4
    rows = []
    for rep in (1, 2, 3):
        cd = f"{cs.ROOT}/round-{rnd}-sofar-r{rep}/sofar/r{rep}"
        for n in cs.CLAUDE_S:
            for sid in cs.session_ids(f"{cd}/artifacts/S{n}/agent.stdout"):
                for p in cs.paths_for(sid, rnd, "sofar", rep):
                    rw = {}
                    uses = []
                    res = {}
                    for line in open(p):
                        e = json.loads(line)
                        if e.get("type") == "attachment":
                            a = e["attachment"]
                            if a.get("hookEvent") == "PreToolUse" and a.get("type") == "hook_success":
                                rw[a.get("toolUseID")] = a.get("stdout", "")
                            continue
                        m = e.get("message") or {}
                        if isinstance(m.get("content"), list):
                            for c in m["content"]:
                                if c.get("type") == "tool_use":
                                    uses.append(c)
                                if c.get("type") == "tool_result":
                                    res[c.get("tool_use_id")] = cs.clen(c.get("content"))
                    for c in uses:
                        if cs.raw_read(c.get("name", ""), c.get("input") or {}, "sofar"):
                            cmd = c["input"].get("command") or json.dumps(c["input"])
                            hit = c["id"] in rw and "updatedInput" in rw[c["id"]]
                            rows.append((rep, n, hit, cmd, res.get(c["id"], 0)))
    why = Counter()
    for rep, n, hit, cmd, nres in rows:
        if hit:
            k = "rewritten"
        elif re.search(r"\b(sed -n|head|tail|grep|rg|wc|awk)\b", cmd):
            k = "partial/search (sed -n, head, tail, grep, wc)"
        elif re.search(r"(^|[;&|]\s*)ls\b|\bfind\b", cmd):
            k = "listing (ls, find)"
        elif re.search(r"\bgit\b", cmd):
            k = "git show/log/diff on .sofar"
        elif re.search(r"\bcat\b", cmd) and ("&&" in cmd or ";" in cmd or "|" in cmd or "2>" in cmd or "echo" in cmd):
            k = "cat inside a compound command"
        elif re.search(r"\bcat\b", cmd):
            k = "plain cat (not rewritten)"
        else:
            k = "other"
        why[k] += 1
    print(f"raw reads {len(rows)}; result chars total {sum(r[4] for r in rows)}")
    for k, v in why.most_common():
        print(f"  {v:4d}  {k}")
    if "-v" in sys.argv:
        for rep, n, hit, cmd, nres in rows:
            print(f"r{rep} S{n} {'RW ' if hit else '-- '} {nres:6d}  {cmd[:200]!r}")

if __name__ == "__main__":
    main()
